sealed interface Command
data class PlaceOrder(val id: String, val qty: Int) : Command
val queue = Channel<Command>(capacity = 64)          // bounded == backpressure
val processor = CoroutineScope(Dispatchers.Default + SupervisorJob())
processor.launch {
    for (cmd in queue) {                             // structured worker
        when (cmd) {
            is PlaceOrder -> placeOrder(cmd)          // exhaustive, no else branch
        }
    }
}
queue.send(PlaceOrder("o-1", 2))                   // suspends when the queue is full
